fn knowledge_curator_state() -> &'static Arc<Mutex<KnowledgeCuratorState>> {
    static STATE: OnceLock<Arc<Mutex<KnowledgeCuratorState>>> = OnceLock::new();
    STATE.get_or_init(|| Arc::new(Mutex::new(KnowledgeCuratorState::default())))
}

