async fn demo_send_http(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(request): Json<DemoSendRequest>,
) -> Result<Json<Value>, (StatusCode, String)> {
    enforce_rate_limit(
        &state,
        authenticated_rate_limit_key("demo_send", &headers),
        RateLimitPolicy {
            max_requests: 20,
            window: Duration::from_secs(60),
        },
    )
    .await?;
    let user = authenticated_user(&state.db, &headers).await?;
    let agents = state
        .db
        .list_managed_agents_by_user(&user.id)
        .await
        .map_err(internal_error)
        .map_err(status_to_http)?;
    let owns_from = agents
        .iter()
        .any(|agent| agent.agent_id == request.from_agent_id);
    let owns_to = agents
        .iter()
        .any(|agent| agent.agent_id == request.to_agent_id);
    if !owns_from || !owns_to {
        return Err((
            StatusCode::FORBIDDEN,
            "selected agents are not managed by this account".to_string(),
        ));
    }

    let thread_id = demo_thread_id(&user.id);
    let message = new_server_message(
        request.from_agent_id,
        vec![request.to_agent_id],
        thread_id,
        "agent_message",
        serde_json::json!({
            "body": request.body.trim(),
            "kind": "demo_message"
        }),
        vec![serde_json::json!({
            "format": "email",
            "content": {
                "subject": "Demo agent message",
                "body": request.body.trim(),
            }
        })],
        vec![],
        vec![],
        true,
    )
    .map_err(|err| (StatusCode::INTERNAL_SERVER_ERROR, err))?;
    let message_id = message.id.clone();

    store_private_app_message(
        &state.db,
        &state.metrics,
        &state.relay_tx,
        &user.id,
        message,
    )
    .await
    .map_err(status_to_http)?;

    Ok(Json(serde_json::json!({
        "success": true,
        "message_id": message_id
    })))
}

// ── Notes message endpoint ────────────────────────────────────────────────────

/// Accepted `type` values for the notes message endpoint.
const NOTES_ALLOWED_TYPES: &[&str] = &[
    crate::message::AFP_TYPE_FOLDER_RULE,
    crate::message::AFP_TYPE_AREA_RULES,
    crate::message::AFP_TYPE_TAG_UPDATE,
];

#[derive(serde::Deserialize)]
struct NoteMessageRequest {
    /// AFP message type: "folder_rule", "area_rules", or "tag_update".
    r#type: String,
    /// Thread to append to. For folder/area rules this is the folder/area id;
    /// for tag_update it should match the source note's thread_id.
    thread_id: String,
    /// Message content. Shape varies by type — see `FolderRuleContent`,
    /// `AreaRulesContent`, `TagUpdateContent` in `src/message.rs`.
    content: serde_json::Value,
    /// For `tag_update`: ids of the original note messages being updated.
    #[serde(default)]
    references: Vec<serde_json::Value>,
}

async fn notes_message_http(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(req): Json<NoteMessageRequest>,
) -> Result<Json<Value>, (StatusCode, String)> {
    if !NOTES_ALLOWED_TYPES.contains(&req.r#type.as_str()) {
        return Err((
            StatusCode::UNPROCESSABLE_ENTITY,
            format!("type must be one of: {}", NOTES_ALLOWED_TYPES.join(", ")),
        ));
    }

    let user = authenticated_user(&state.db, &headers).await?;

    let agents = state
        .db
        .list_managed_agents_by_user(&user.id)
        .await
        .map_err(internal_error)
        .map_err(status_to_http)?;

    // Use the user's first managed agent, or derive a stable notes agent id.
    let from_agent = agents
        .first()
        .map(|a| a.agent_id.clone())
        .unwrap_or_else(|| format!("agent:notes@{}", user.id));

    let message = new_server_message(
        from_agent,
        vec![],
        req.thread_id,
        &req.r#type,
        req.content,
        vec![],
        req.references,
        vec![],
        true,
    )
    .map_err(|e| (StatusCode::INTERNAL_SERVER_ERROR, e))?;

    let message_id = message.id.clone();

    store_private_app_message(
        &state.db,
        &state.metrics,
        &state.relay_tx,
        &user.id,
        message,
    )
    .await
    .map_err(status_to_http)?;

    Ok(Json(serde_json::json!({
        "success": true,
        "message_id": message_id
    })))
}

