/// GET /workflows/{id}/runs/{run_id}/stream — SSE stream replaying stored timeline events.
///
/// Emits server-sent events in order derived from the run's `timeline_json`.
/// Event sequence per node: `node_started` → `node_completed` | `node_failed` | `policy_block` | `wait_for_approval`
/// Terminal events: `run_completed` | `run_failed`
/// Each event is JSON: `{ "event": "...", "node_id": "...", "label": "...", "status": "...", "index": N, "ts": "..." }`
async fn workflow_run_stream_http(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Path((workflow_id, run_id)): Path<(String, String)>,
) -> Result<axum::response::Response, (StatusCode, String)> {
    let user = authenticated_user(&state.db, &headers).await?;
    let run = state
        .db
        .get_workflow_run(&user.id, &workflow_id, &run_id)
        .await
        .map_err(|err| {
            if matches!(err, sqlx::Error::RowNotFound) {
                (StatusCode::NOT_FOUND, "run not found".to_string())
            } else {
                status_to_http(internal_error(err))
            }
        })?;

    let timeline = run
        .get("timeline_json")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();
    let run_status = run
        .get("status")
        .and_then(Value::as_str)
        .unwrap_or("completed")
        .to_string();

    // Build the SSE body as a newline-delimited text/event-stream.
    // We emit all events immediately (no sleep) — the frontend animates progress.
    let mut body = String::new();

    // run_started
    let run_started = serde_json::json!({
        "event": "run_started",
        "run_id": run_id,
        "workflow_id": workflow_id,
        "status": "running",
        "node_count": timeline.len(),
    });
    body.push_str(&format!("data: {}\n\n", run_started));

    for (index, node) in timeline.iter().enumerate() {
        let node_id = node
            .get("source_node_id")
            .and_then(Value::as_str)
            .or_else(|| node.get("node_id").and_then(Value::as_str))
            .unwrap_or("unknown");
        let label = node
            .get("label")
            .and_then(Value::as_str)
            .or_else(|| node.get("graph_node_label").and_then(Value::as_str))
            .unwrap_or("Node");
        let node_status = node
            .get("status")
            .and_then(Value::as_str)
            .unwrap_or("completed");
        let runtime_kind = node
            .get("runtime_kind")
            .and_then(Value::as_str)
            .unwrap_or("agent");
        let started_at = node
            .get("started_at")
            .and_then(Value::as_str)
            .or_else(|| node.get("ts").and_then(Value::as_str))
            .unwrap_or("");

        // node_started
        let node_started = serde_json::json!({
            "event": "node_started",
            "node_id": node_id,
            "label": label,
            "runtime_kind": runtime_kind,
            "index": index,
            "ts": started_at,
        });
        body.push_str(&format!("data: {}\n\n", node_started));

        // terminal node event
        let terminal_event = match node_status {
            "failed" => "node_failed",
            "blocked" | "policy_block" => "policy_block",
            "waiting_for_approval" => "wait_for_approval",
            "skipped" => "node_skipped",
            _ => "node_completed",
        };
        let finished_at = node
            .get("finished_at")
            .and_then(Value::as_str)
            .or_else(|| node.get("completed_at").and_then(Value::as_str))
            .unwrap_or("");
        let reason = node
            .get("failure_reason")
            .and_then(Value::as_str)
            .or_else(|| node.get("block_reason").and_then(Value::as_str))
            .or_else(|| node.get("approval_reason").and_then(Value::as_str))
            .map(str::to_string);
        let mut terminal = serde_json::json!({
            "event": terminal_event,
            "node_id": node_id,
            "label": label,
            "status": node_status,
            "index": index,
            "ts": finished_at,
        });
        if let Some(r) = reason {
            terminal["reason"] = Value::String(r);
        }
        body.push_str(&format!("data: {}\n\n", terminal));
    }

    // terminal run event
    let terminal_run_event = if run_status == "failed" {
        "run_failed"
    } else {
        "run_completed"
    };
    let run_terminal = serde_json::json!({
        "event": terminal_run_event,
        "run_id": run_id,
        "status": run_status,
        "node_count": timeline.len(),
        "ts": run.get("completed_at").and_then(Value::as_str).unwrap_or(""),
    });
    body.push_str(&format!("data: {}\n\n", run_terminal));

    Ok(axum::response::Response::builder()
        .status(StatusCode::OK)
        .header("Content-Type", "text/event-stream")
        .header("Cache-Control", "no-cache")
        .header("X-Accel-Buffering", "no")
        .body(axum::body::Body::from(body))
        .unwrap())
}

