#[derive(serde::Deserialize)]
struct LlmConfigRequest {
    backend: String,
    #[serde(default)]
    provider: Option<String>,
    #[serde(default)]
    model: Option<String>,
    #[serde(default)]
    api_key: Option<String>,
    #[serde(default)]
    ollama_url: Option<String>,
}

// ── LLM config ────────────────────────────────────────────────────────────────

async fn llm_config_get_http(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
) -> Result<Json<Value>, (StatusCode, String)> {
    let user = authenticated_user(&state.db, &headers).await?;
    state
        .db
        .get_llm_config(&user.id)
        .await
        .map_err(internal_error)
        .map_err(status_to_http)?
        .map(Json)
        .ok_or_else(|| {
            (
                StatusCode::NOT_FOUND,
                "no LLM config; call POST /agent/provision first".to_string(),
            )
        })
}

async fn llm_config_set_http(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(body): Json<LlmConfigRequest>,
) -> Result<Json<Value>, (StatusCode, String)> {
    let user = authenticated_user(&state.db, &headers).await?;
    let (backend, monthly_budget) = match body.backend.as_str() {
        "hosted" => {
            let billing = state
                .db
                .get_billing_status(&user.id)
                .await
                .unwrap_or_default();
            if billing
                .get("plan")
                .and_then(|p| p.as_str())
                .unwrap_or("free")
                != "pro"
            {
                return Err((
                    StatusCode::PAYMENT_REQUIRED,
                    "hosted LLM requires pro plan ($9/mo)".to_string(),
                ));
            }
            (LlmBackend::Hosted, 900i32)
        }
        "byok" => (LlmBackend::Byok, 0i32),
        "ollama" => (LlmBackend::Ollama, 0i32),
        "runpod" => (LlmBackend::RunPod, 0i32),
        other => return Err((StatusCode::BAD_REQUEST, format!("unknown backend: {other}"))),
    };
    let provider = body.provider.unwrap_or_else(|| "anthropic".to_string());
    let default_model = if matches!(backend, LlmBackend::RunPod) {
        "Qwen/Qwen3.5-35B-A3B".to_string()
    } else {
        "claude-haiku-4-5-20251001".to_string()
    };
    let cfg = LlmConfig {
        id: Ulid::new().to_string(),
        owner_user_id: user.id.clone(),
        backend,
        provider: provider.clone(),
        model: body.model.unwrap_or(default_model),
        encrypted_api_key: body.api_key,
        ollama_url: body.ollama_url,
        monthly_budget_cents: monthly_budget,
        usage_cents_current_month: 0,
    };
    state
        .db
        .upsert_llm_config(&cfg)
        .await
        .map_err(internal_error)
        .map_err(status_to_http)?;
    Ok(Json(llm_config_save_response(&cfg)))
}

fn llm_backend_label(backend: &LlmBackend) -> &'static str {
    match backend {
        LlmBackend::Hosted => "hosted",
        LlmBackend::Byok => "byok",
        LlmBackend::Ollama => "ollama",
        LlmBackend::RunPod => "runpod",
    }
}

fn llm_config_save_response(cfg: &LlmConfig) -> Value {
    serde_json::json!({
        "updated": true,
        "backend": llm_backend_label(&cfg.backend),
        "provider": cfg.provider,
        "model": cfg.model,
        "monthly_budget_cents": cfg.monthly_budget_cents,
        "usage_cents_current_month": cfg.usage_cents_current_month,
    })
}

// ── LLM ping — verify connection without triggering inference ─────────────────

async fn llm_config_ping_http(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
) -> Result<Json<Value>, (StatusCode, String)> {
    let user = authenticated_user(&state.db, &headers).await?;
    let cfg = state
        .db
        .get_llm_config(&user.id)
        .await
        .map_err(internal_error)
        .map_err(status_to_http)?
        .ok_or_else(|| (StatusCode::NOT_FOUND, "no LLM config saved yet".to_string()))?;

    let client = reqwest::Client::builder()
        .timeout(std::time::Duration::from_secs(10))
        .build()
        .map_err(|e| (StatusCode::INTERNAL_SERVER_ERROR, e.to_string()))?;

    match cfg
        .get("backend")
        .and_then(|b| b.as_str())
        .unwrap_or("byok")
    {
        "runpod" => {
            let ep = std::env::var("OMNYID_RUNPOD_ENDPOINT_ID").unwrap_or_default();
            let api_key = cfg
                .get("encrypted_api_key")
                .and_then(|k| k.as_str())
                .filter(|k| !k.is_empty())
                .map(|k| k.to_string())
                .unwrap_or_else(|| std::env::var("OMNYID_RUNPOD_API_KEY").unwrap_or_default());
            if ep.is_empty() {
                return Ok(Json(
                    serde_json::json!({ "ok": false, "reason": "RunPod endpoint ID not configured on server" }),
                ));
            }
            let url = format!("https://api.runpod.ai/v2/{ep}/openai/v1/models");
            let resp = client
                .get(&url)
                .bearer_auth(&api_key)
                .send()
                .await
                .map_err(|e| (StatusCode::BAD_GATEWAY, format!("RunPod unreachable: {e}")))?;
            let status = resp.status();
            if status.is_success() {
                Ok(Json(
                    serde_json::json!({ "ok": true, "backend": "runpod", "http_status": status.as_u16() }),
                ))
            } else {
                let body = resp.text().await.unwrap_or_default();
                Ok(Json(
                    serde_json::json!({ "ok": false, "backend": "runpod", "http_status": status.as_u16(), "reason": body }),
                ))
            }
        }
        "ollama" => {
            let base = cfg
                .get("ollama_url")
                .and_then(|u| u.as_str())
                .unwrap_or("http://localhost:11434");
            let url = format!("{base}/api/tags");
            let resp = client
                .get(&url)
                .send()
                .await
                .map_err(|e| (StatusCode::BAD_GATEWAY, format!("Ollama unreachable: {e}")))?;
            let status = resp.status();
            if status.is_success() {
                Ok(Json(
                    serde_json::json!({ "ok": true, "backend": "ollama", "http_status": status.as_u16() }),
                ))
            } else {
                Ok(Json(
                    serde_json::json!({ "ok": false, "backend": "ollama", "http_status": status.as_u16(), "reason": "Ollama responded with an error" }),
                ))
            }
        }
        "byok" => {
            // For BYOK (Anthropic/OpenAI), list models — no tokens consumed
            let provider = cfg
                .get("provider")
                .and_then(|p| p.as_str())
                .unwrap_or("anthropic");
            let api_key = cfg
                .get("encrypted_api_key")
                .and_then(|k| k.as_str())
                .unwrap_or("");
            let request = match provider {
                "openai" => client
                    .get("https://api.openai.com/v1/models")
                    .bearer_auth(api_key),
                "openrouter" => client
                    .get("https://openrouter.ai/api/v1/models")
                    .bearer_auth(api_key),
                "cerebras" => client
                    .get("https://api.cerebras.ai/v1/models")
                    .bearer_auth(api_key),
                "together_ai" => client
                    .get("https://api.together.xyz/v1/models")
                    .bearer_auth(api_key),
                _ => client
                    .get("https://api.anthropic.com/v1/models")
                    .header("x-api-key", api_key)
                    .header("anthropic-version", "2023-06-01"),
            };
            let resp = request
                .send()
                .await
                .map_err(|e| (StatusCode::BAD_GATEWAY, format!("API unreachable: {e}")))?;
            let status = resp.status();
            if status.is_success() {
                Ok(Json(
                    serde_json::json!({ "ok": true, "backend": "byok", "provider": provider, "http_status": status.as_u16() }),
                ))
            } else {
                Ok(Json(
                    serde_json::json!({ "ok": false, "backend": "byok", "provider": provider, "http_status": status.as_u16(), "reason": "API key rejected or unreachable" }),
                ))
            }
        }
        other => Ok(Json(
            serde_json::json!({ "ok": false, "reason": format!("unsupported backend: {other}") }),
        )),
    }
}

// ── /ui/decision — record user decision for a generative card decision_point ─

async fn ui_decision_http(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(body): Json<UiDecisionRequest>,
) -> Result<Json<Value>, (StatusCode, String)> {
    let user = authenticated_user(&state.db, &headers).await?;

    // Store as an AFP user_decision message in the thread so the running agent
    // can pick it up via its relay WebSocket subscription.
    let decision_msg = AFPMessage {
        protocol: "afp-v1".to_string(),
        id: Ulid::new().to_string(),
        thread_id: body.thread_id.clone(),
        parent_id: None,
        from: user.id.clone(),
        to: body.agent_id.clone().map(|a| vec![a]).unwrap_or_default(),
        timestamp: chrono::Utc::now().to_rfc3339(),
        r#type: "user_decision".to_string(),
        subtype: Some("decision_point".to_string()),
        content: serde_json::json!({
            "card_id":            body.card_id,
            "decision_point_id":  body.decision_point_id,
            "selected_option_id": body.selected_option_id,
            "decided_by":         user.id,
        }),
        metadata: Some(serde_json::json!({
            "origin": "workspace_ui_decision"
        })),
        views: vec![],
        attachments: vec![],
        references: vec![],
        encryption: None,
        signature: String::new(),
        store_in_relational: true,
        prev_hash: None,
    };

    let decision_message_id = decision_msg.id.clone();
    store_private_app_message(
        &state.db,
        &state.metrics,
        &state.relay_tx,
        &user.id,
        decision_msg,
    )
    .await
    .map_err(status_to_http)?;

    if body.decision_point_id == "approval_gate" || body.decision_point_id == "clarification_gate" {
        let thread_messages =
            thread_messages_for_headers(&state.db, &headers, &body.thread_id).await?;
        let app_messages = thread_messages
            .into_iter()
            .map(proto_to_app)
            .collect::<Vec<_>>();
        if let Some(card_message) = app_messages.iter().find(|message| {
            message.r#type == "generative_card"
                && message.content.get("card_id").and_then(Value::as_str)
                    == Some(body.card_id.as_str())
        }) {
            let objective = card_message
                .content
                .get("query")
                .and_then(Value::as_str)
                .unwrap_or_default()
                .to_string();

            let is_approval_confirm = body.selected_option_id == "confirm_orchestration";
            let clarification_instruction =
                clarification_option_instruction(&body.selected_option_id);
            let is_clarification_proceed = body.decision_point_id == "clarification_gate"
                && clarification_instruction.is_some();

            if (is_approval_confirm || is_clarification_proceed) && !objective.is_empty() {
                let llm_cfg = state
                    .db
                    .get_llm_config(&user.id)
                    .await
                    .map_err(internal_error)
                    .map_err(status_to_http)?
                    .ok_or_else(|| {
                        (
                            StatusCode::BAD_REQUEST,
                            "no LLM config; call POST /user/llm-config".to_string(),
                        )
                    })?;
                let backend_name = llm_cfg["backend"].as_str().unwrap_or("hosted").to_string();
                let (api_key, model) = if backend_name == "runpod" {
                    (
                        std::env::var("OMNYID_RUNPOD_API_KEY").unwrap_or_default(),
                        llm_cfg["model"]
                            .as_str()
                            .unwrap_or("Qwen/Qwen3.5-35B-A3B")
                            .to_string(),
                    )
                } else {
                    (
                        std::env::var("OMNYID_ANTHROPIC_KEY")
                            .or_else(|_| std::env::var("ANTHROPIC_API_KEY"))
                            .unwrap_or_default(),
                        llm_cfg["model"]
                            .as_str()
                            .unwrap_or("claude-haiku-4-5-20251001")
                            .to_string(),
                    )
                };
                let master_instance = state
                    .db
                    .get_master_agent_instance(&user.id)
                    .await
                    .map_err(internal_error)
                    .map_err(status_to_http)?
                    .ok_or_else(|| (StatusCode::NOT_FOUND, "no master agent".to_string()))?;
                let lora_active = master_instance["lora_genome_active"]
                    .as_bool()
                    .unwrap_or(false);
                let agent_id = master_instance["agent_id"].as_str().map(str::to_string);
                let orchestration_objective = if body.decision_point_id == "clarification_gate" {
                    apply_clarification_context(&objective, &body.selected_option_id)
                } else {
                    objective.clone()
                };

                if let Some(agent_id_value) = agent_id.clone() {
                    if body.decision_point_id == "clarification_gate"
                        || body.decision_point_id == "approval_gate"
                    {
                        let (title, text, tone) = if body.decision_point_id == "clarification_gate"
                        {
                            clarification_option_summary(&body.selected_option_id)
                        } else {
                            approval_option_summary(&body.selected_option_id)
                        };
                        let section_id = if body.decision_point_id == "clarification_gate" {
                            "clarification_gate"
                        } else {
                            "approval_gate"
                        };
                        let assumption_update = serde_json::json!({
                            "card_id": body.card_id,
                            "section": {
                                "id": section_id,
                                "type": "callout",
                                "order": 3,
                                "status": "complete",
                                "content": {
                                    "title": title,
                                    "text": text,
                                    "tone": tone,
                                }
                            }
                        });
                        if let Ok(msg) = new_server_message(
                            agent_id_value.clone(),
                            vec![],
                            body.thread_id.clone(),
                            "card_section_update",
                            assumption_update,
                            vec![],
                            vec![],
                            vec![],
                            true,
                        ) {
                            let _ = store_private_app_message(
                                &state.db,
                                &state.metrics,
                                &state.relay_tx,
                                &user.id,
                                msg,
                            )
                            .await;
                        }
                    }

                    let update = serde_json::json!({
                        "card_id": body.card_id,
                        "section": {
                            "id": "progress",
                            "type": "progress",
                            "order": 1,
                            "status": "streaming",
                            "content": {
                                "text": if body.decision_point_id == "clarification_gate" {
                                    clarification_option_progress_text(&body.selected_option_id)
                                } else {
                                    "Approval received. Starting orchestration now."
                                },
                                "pct": 25
                            }
                        }
                    });
                    if let Ok(msg) = new_server_message(
                        agent_id_value,
                        vec![],
                        body.thread_id.clone(),
                        "card_section_update",
                        update,
                        vec![],
                        vec![],
                        vec![],
                        true,
                    ) {
                        let _ = store_private_app_message(
                            &state.db,
                            &state.metrics,
                            &state.relay_tx,
                            &user.id,
                            msg,
                        )
                        .await;
                    }
                }

                spawn_orchestration_run(
                    state.clone(),
                    user.id.clone(),
                    api_key,
                    model,
                    backend_name,
                    orchestration_objective,
                    lora_active,
                    body.thread_id.clone(),
                    body.card_id.clone(),
                    agent_id,
                );
            } else if body.selected_option_id == "cancel_orchestration"
                || body.selected_option_id == "cancel_for_clarification"
            {
                let master_instance = state
                    .db
                    .get_master_agent_instance(&user.id)
                    .await
                    .map_err(internal_error)
                    .map_err(status_to_http)?
                    .ok_or_else(|| (StatusCode::NOT_FOUND, "no master agent".to_string()))?;
                if let Some(agent_id) = master_instance["agent_id"].as_str() {
                    if body.decision_point_id == "approval_gate" {
                        let (title, text, tone) = approval_option_summary(&body.selected_option_id);
                        let approval_update = serde_json::json!({
                            "card_id": body.card_id,
                            "section": {
                                "id": "approval_gate",
                                "type": "callout",
                                "order": 3,
                                "status": "complete",
                                "content": {
                                    "title": title,
                                    "text": text,
                                    "tone": tone,
                                }
                            }
                        });
                        if let Ok(msg) = new_server_message(
                            agent_id.to_string(),
                            vec![],
                            body.thread_id.clone(),
                            "card_section_update",
                            approval_update,
                            vec![],
                            vec![],
                            vec![],
                            true,
                        ) {
                            let _ = store_private_app_message(
                                &state.db,
                                &state.metrics,
                                &state.relay_tx,
                                &user.id,
                                msg,
                            )
                            .await;
                        }
                    }

                    let update = serde_json::json!({
                        "card_id": body.card_id,
                        "section": {
                            "id": "final",
                            "type": "final_answer",
                            "order": 4,
                            "status": "complete",
                            "content": {
                                "text": if body.decision_point_id == "clarification_gate" {
                                    "Orchestration cancelled until a more specific objective is provided."
                                } else {
                                    "Orchestration cancelled before any external action was started."
                                }
                            }
                        }
                    });
                    if let Ok(msg) = new_server_message(
                        agent_id.to_string(),
                        vec![],
                        body.thread_id.clone(),
                        "card_section_update",
                        update,
                        vec![],
                        vec![],
                        vec![],
                        true,
                    ) {
                        let _ = store_private_app_message(
                            &state.db,
                            &state.metrics,
                            &state.relay_tx,
                            &user.id,
                            msg,
                        )
                        .await;
                    }
                }
            }
        }
    }

    Ok(Json(serde_json::json!({
        "success":    true,
        "message_id": decision_message_id,
    })))
}

// ── /user/agent-preferences — get/set agent optimization preferences ──────────

async fn agent_preferences_get_http(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
) -> Result<Json<AgentPreferences>, (StatusCode, String)> {
    let user = authenticated_user(&state.db, &headers).await?;

    let prefs = state
        .db
        .get_agent_preferences(&user.id)
        .await
        .ok()
        .flatten()
        .and_then(|v| serde_json::from_value::<AgentPreferences>(v).ok())
        .unwrap_or_default();

    Ok(Json(prefs))
}

async fn agent_preferences_set_http(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(body): Json<AgentPreferences>,
) -> Result<Json<Value>, (StatusCode, String)> {
    let user = authenticated_user(&state.db, &headers).await?;

    let valid_modes = ["speed", "cost", "balanced"];
    if !valid_modes.contains(&body.optimization_mode.as_str()) {
        return Err((
            StatusCode::BAD_REQUEST,
            format!(
                "optimization_mode must be one of: {}",
                valid_modes.join(", ")
            ),
        ));
    }

    state
        .db
        .upsert_agent_preferences(
            &user.id,
            &body.optimization_mode,
            body.auto_confirm_threshold_cents,
            body.show_cost_estimates,
            body.default_store_in_history,
        )
        .await
        .map_err(internal_error)
        .map_err(status_to_http)?;

    Ok(Json(serde_json::json!({"updated": true})))
}

async fn daemons_list_http(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
) -> Result<Json<Value>, (StatusCode, String)> {
    let user = authenticated_user(&state.db, &headers).await?;
    let daemons = daemon_registry::get_active_daemons(&state.db, &user.id)
        .await
        .map_err(internal_error)
        .map_err(status_to_http)?;
    let warnings = daemon_registry::daemon_health_check(&state.db)
        .await
        .map_err(internal_error)
        .map_err(status_to_http)?;
    let stale_map = warnings
        .into_iter()
        .filter(|warning| warning.user_id == user.id)
        .map(|warning| (warning.daemon_id, warning.stale_minutes))
        .collect::<HashMap<_, _>>();
    let items = daemons
        .into_iter()
        .map(|daemon| {
            serde_json::json!({
                "daemon_id": daemon.daemon_id,
                "daemon_kind": format!("{:?}", daemon.daemon_kind).to_lowercase(),
                "display_name": daemon.daemon_kind.display_name(),
                "status": format!("{:?}", daemon.status).to_lowercase(),
                "workflow_id": daemon.workflow_id,
                "delegated_key_id": daemon.delegated_key_id,
                "last_heartbeat_at": daemon.last_heartbeat_at,
                "created_at": daemon.created_at,
                "revoked_at": daemon.revoked_at,
                "policy_config": daemon.policy_config,
                "stale_minutes": stale_map.get(&daemon.daemon_id).copied(),
            })
        })
        .collect::<Vec<_>>();
    Ok(Json(serde_json::json!({ "daemons": items })))
}

async fn daemon_heartbeat_http(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Path(daemon_id): Path<String>,
) -> Result<Json<Value>, (StatusCode, String)> {
    let user = authenticated_user(&state.db, &headers).await?;
    let registration = daemon_registry::get_daemon_registration(&state.db, &daemon_id)
        .await
        .map_err(internal_error)
        .map_err(status_to_http)?
        .ok_or_else(|| (StatusCode::NOT_FOUND, "daemon not found".to_string()))?;
    if registration.user_id != user.id {
        return Err((
            StatusCode::FORBIDDEN,
            "daemon not owned by this user".to_string(),
        ));
    }
    let heartbeat = daemon_registry::get_latest_heartbeat(&state.db, &daemon_id)
        .await
        .map_err(internal_error)
        .map_err(status_to_http)?;
    Ok(Json(serde_json::json!({
        "daemon": registration,
        "heartbeat": heartbeat,
    })))
}

async fn daemon_revoke_http(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Path(daemon_id): Path<String>,
) -> Result<Json<Value>, (StatusCode, String)> {
    let user = authenticated_user(&state.db, &headers).await?;
    let registration = daemon_registry::get_daemon_registration(&state.db, &daemon_id)
        .await
        .map_err(internal_error)
        .map_err(status_to_http)?
        .ok_or_else(|| (StatusCode::NOT_FOUND, "daemon not found".to_string()))?;
    if registration.user_id != user.id {
        return Err((
            StatusCode::FORBIDDEN,
            "daemon not owned by this user".to_string(),
        ));
    }
    daemon_registry::revoke_daemon(&state.db, &daemon_id)
        .await
        .map_err(internal_error)
        .map_err(status_to_http)?;
    Ok(Json(serde_json::json!({
        "updated": true,
        "daemon_id": daemon_id,
        "status": "revoked",
    })))
}

// ── Knowledge Curator — backlinks & supertags ─────────────────────────────────

/// `GET /notes/backlinks/{message_id}`
///
/// Returns all backlink edges (both inbound and outbound) for the given AFP
/// message id.  Uses the `afp_backlinks` derived index — never scans raw
/// `backlink_update` history.
async fn note_backlinks_http(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Path(message_id): Path<String>,
) -> Result<Json<Value>, (StatusCode, String)> {
    let user = authenticated_user(&state.db, &headers).await?;
    let backlinks = state
        .db
        .list_backlinks_for_message(&user.id, &message_id)
        .await
        .map_err(internal_error)
        .map_err(status_to_http)?;
    let items: Vec<Value> = backlinks
        .into_iter()
        .map(|record| {
            serde_json::json!({
                "backlink_id": record.backlink_id,
                "source_id":   record.source_id,
                "target_id":   record.target_id,
                "direction":   if record.source_id == message_id { "outbound" } else { "inbound" },
                "link_kind":   format!("{:?}", record.link_kind).to_lowercase(),
                "similarity":  record.similarity,
                "entities":    record.entities,
                "created_at":  record.created_at,
            })
        })
        .collect();
    let count = items.len();
    Ok(Json(serde_json::json!({
        "message_id": message_id,
        "backlinks":  items,
        "count":      count,
    })))
}

/// `GET /notes/supertags`
///
