/// `POST /notes/{message_id}/backlink-override`
///
/// Stores a `backlink_override` AFP message that the Knowledge Curator will
/// respect on the next processing pass for this message.
///
/// Body: `{ "suppress": bool, "rules": "...", "scope": "message" | "thread" }`
async fn note_backlink_override_http(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Path(message_id): Path<String>,
    Json(body): Json<Value>,
) -> Result<Json<Value>, (StatusCode, String)> {
    let user = authenticated_user(&state.db, &headers).await?;
    let suppress = body
        .get("suppress")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    let rules = body
        .get("rules")
        .and_then(Value::as_str)
        .filter(|s| !s.trim().is_empty())
        .map(str::to_string);
    let scope_str = body
        .get("scope")
        .and_then(Value::as_str)
        .unwrap_or("message");
    let thread_id = body
        .get("thread_id")
        .and_then(Value::as_str)
        .unwrap_or("")
        .to_string();

    let content = serde_json::json!({
        "source_id":  message_id,
        "thread_id":  if thread_id.is_empty() { Value::Null } else { Value::String(thread_id.clone()) },
        "scope":      scope_str,
        "suppress":   suppress,
        "rules":      rules,
    });

    let msg = crate::afp::Message {
        protocol: "afp-v1".to_string(),
        id: format!("backlink-override.{}", Ulid::new()),
        thread_id: if thread_id.is_empty() {
            format!("thread.backlink-override.{message_id}")
        } else {
            thread_id
        },
        parent_id: String::new(),
        from: format!("omnyid://user/{}", user.id),
        to: vec!["omnyid://workspace/user".to_string()],
        timestamp: chrono::Utc::now().to_rfc3339(),
        r#type: crate::message::AFP_TYPE_BACKLINK_OVERRIDE.to_string(),
        content: content.to_string(),
        signature: String::new(),
        encryption: "{}".to_string(),
        views: "[]".to_string(),
        references: serde_json::json!([message_id]).to_string(),
        attachments: "[]".to_string(),
        store_in_relational: false,
        subtype: scope_str.to_string(),
        metadata: serde_json::json!({ "source_id": message_id }).to_string(),
    };
    state
        .db
        .store_private_message(&user.id, &msg, content)
        .await
        .map_err(internal_error)
        .map_err(status_to_http)?;

    Ok(Json(serde_json::json!({
        "stored": true,
        "message_id": message_id,
        "suppress": suppress,
        "scope": scope_str,
    })))
}

// ── Multi-hop backlink graph ───────────────────────────────────────────────────

/// `GET /backlinks/graph?root={id}&depth={n}`
///
/// BFS traversal of the backlink graph starting from `root`, up to `depth`
/// hops (max 4).  Returns all reachable nodes and edges as a JSON graph
/// suitable for force-directed visualisation.
async fn backlinks_graph_http(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Query(params): Query<std::collections::HashMap<String, String>>,
) -> Result<Json<Value>, (StatusCode, String)> {
    let user = authenticated_user(&state.db, &headers).await?;
    let root = params
        .get("root")
        .filter(|s| !s.is_empty())
        .ok_or_else(|| (StatusCode::BAD_REQUEST, "root query parameter required".to_string()))?
        .clone();
    let depth: u32 = params
        .get("depth")
        .and_then(|s| s.parse().ok())
        .unwrap_or(2)
        .min(4);

    let (nodes, edges) = state
        .db
        .bfs_backlinks_graph(&user.id, &root, depth)
        .await
        .map_err(internal_error)
        .map_err(status_to_http)?;

    let edge_values: Vec<Value> = edges
        .into_iter()
        .map(|record| {
            serde_json::json!({
                "backlink_id": record.backlink_id,
                "source_id":   record.source_id,
                "target_id":   record.target_id,
                "link_kind":   format!("{:?}", record.link_kind).to_lowercase(),
                "similarity":  record.similarity,
                "entities":    record.entities,
                "created_at":  record.created_at,
            })
        })
        .collect();
    let node_count = nodes.len();
    let edge_count = edge_values.len();

    Ok(Json(serde_json::json!({
        "root":   root,
        "depth":  depth,
        "nodes":  nodes,
        "edges":  edge_values,
        "node_count": node_count,
        "edge_count": edge_count,
    })))
}

// ── Default supertag taxonomy install ─────────────────────────────────────────

/// Default taxonomy to seed.  Each entry is `(tag_name, keywords)`.
const DEFAULT_SUPERTAG_TAXONOMY: &[(&str, &[&str])] = &[
    ("#Work",      &["meeting", "standup", "sprint", "deadline", "milestone", "jira", "ticket", "project", "client", "proposal"]),
    ("#Personal",  &["birthday", "anniversary", "family", "holiday", "weekend", "personal", "home"]),
    ("#Health",    &["gym", "workout", "doctor", "appointment", "medication", "therapy", "wellness", "run", "exercise"]),
    ("#Finance",   &["invoice", "payment", "salary", "tax", "budget", "expense", "receipt", "bank", "subscription"]),
    ("#Travel",    &["flight", "hotel", "airport", "visa", "booking", "trip", "travel", "itinerary", "passport"]),
    ("#Learning",  &["course", "lecture", "study", "tutorial", "book", "reading", "workshop", "certification"]),
    ("#Ideas",     &["idea", "brainstorm", "concept", "hypothesis", "experiment", "prototype", "draft"]),
    ("#Urgent",    &["urgent", "asap", "critical", "blocker", "p0", "hotfix", "fire", "outage"]),
];

/// `POST /notes/supertags/install-defaults`
///
/// One-click install of the default supertag taxonomy.  Writes one
/// `supertag_definition` AFP message per tag.  Idempotent — safe to call
/// multiple times.
async fn install_default_supertags_http(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
) -> Result<Json<Value>, (StatusCode, String)> {
    use crate::message::AFP_TYPE_SUPERTAG_DEFINITION;

    let user = authenticated_user(&state.db, &headers).await?;
    let mut installed: Vec<String> = Vec::new();

    for (tag_name, keywords) in DEFAULT_SUPERTAG_TAXONOMY {
        let content = serde_json::json!({
            "tag_name":     tag_name,
            "keywords":     keywords,
            "folder_scope": [],
        });
        let slug = tag_name.trim_start_matches('#').to_lowercase();
        let msg = crate::afp::Message {
            protocol: "afp-v1".to_string(),
            id: format!("supertag-def.{}.{}", slug, Ulid::new()),
            thread_id: format!("thread.supertag-def.{slug}"),
            parent_id: String::new(),
            from: format!("omnyid://user/{}", user.id),
            to: vec!["omnyid://workspace/user".to_string()],
            timestamp: chrono::Utc::now().to_rfc3339(),
            r#type: AFP_TYPE_SUPERTAG_DEFINITION.to_string(),
            content: content.to_string(),
            signature: String::new(),
            encryption: "{}".to_string(),
            views: "[]".to_string(),
            references: "[]".to_string(),
            attachments: "[]".to_string(),
            store_in_relational: false,
            subtype: String::new(),
            metadata: "{}".to_string(),
        };
        if let Err(e) = state.db.store_private_message(&user.id, &msg, content).await {
            tracing::warn!("install_default_supertags: skipped {tag_name}: {e}");
            continue;
        }
        installed.push(tag_name.to_string());
    }

    let count = installed.len();
    Ok(Json(serde_json::json!({
        "installed": installed,
        "count": count,
    })))
}

async fn mcp_http(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(req): Json<crate::mcp_server::McpRequest>,
) -> Result<Json<crate::mcp_server::McpResponse>, (StatusCode, String)> {
    // MCP auth is optional — unauthenticated clients get tool list but not data
    let user_id = authenticated_user(&state.db, &headers)
        .await
        .ok()
        .map(|u| u.id);
    let resp = crate::mcp_server::dispatch_mcp_request(req, &state.db, user_id.as_deref()).await;
    Ok(Json(resp))
}

async fn verify_thread_chain_http(
    State(state): State<Arc<AppState>>,
    Path(thread_id): Path<String>,
    headers: HeaderMap,
) -> Result<Json<Value>, (StatusCode, String)> {
    // Allow both authenticated and unauthenticated verify (read-only integrity check)
    let messages = state
        .db
        .get_thread(&thread_id)
        .await
        .map_err(internal_error)
        .map_err(status_to_http)?;
    let msg_values: Vec<Value> = messages
        .iter()
        .map(|m| {
            serde_json::json!({
                "id": m.id,
                "thread_id": m.thread_id,
                "from": m.from,
                "timestamp": m.timestamp,
                "type": m.r#type,
            })
        })
        .collect();
    let _ = headers; // available for future auth-gated verify
    match crate::audit_chain::verify_chain(&msg_values) {
        Ok(()) => Ok(Json(serde_json::json!({
            "thread_id": thread_id,
            "message_count": msg_values.len(),
            "chain_valid": true,
        }))),
        Err(broken_at) => Ok(Json(serde_json::json!({
            "thread_id": thread_id,
            "message_count": msg_values.len(),
            "chain_valid": false,
            "broken_at_index": broken_at,
        }))),
    }
}

