    #[test]
    fn server_generated_encrypted_messages_do_not_keep_plaintext_views() {
        let _guard = env_test_lock().lock().expect("env test lock");
        unsafe {
            std::env::set_var(
                "OMNYID_ENCRYPTION_KEY_HEX",
                "7190136af4de06db4b36c641be88c682ecd9866986b70af49f68a9b2bc6716cc",
            );
            std::env::set_var(
                "OMNYID_SIGNING_KEY_HEX",
                "4fc83507eef94f7686079409f466e0d44478dc5f8537c67298785e36f6c00534",
            );
        }

        let message = new_server_message(
            "agent:test-alpha@omnyid.com".to_string(),
            vec!["agent:test-beta@omnyid.com".to_string()],
            "thread.demo".to_string(),
            "agent_message",
            serde_json::json!({"body": "hello"}),
            vec![serde_json::json!({"format": "email", "content": {"body": "hello"}})],
            vec![],
            vec![],
            true,
        )
        .expect("server message");

        assert!(message.encryption.is_some());
        assert!(message.views.is_empty());
        assert_eq!(message.r#type, "agent");
        assert_eq!(message.subtype.as_deref(), Some("message"));
        assert_eq!(
            message
                .metadata
                .as_ref()
                .and_then(|metadata| metadata.get("legacy_type"))
                .and_then(serde_json::Value::as_str),
            Some("agent_message")
        );

        unsafe {
            std::env::remove_var("OMNYID_ENCRYPTION_KEY_HEX");
            std::env::remove_var("OMNYID_SIGNING_KEY_HEX");
        }
    }

    // ── Cron scheduler unit tests ─────────────────────────────────────────────

    #[test]
    fn cron_to_quartz_expands_five_field_expression_and_converts_dow() {
        // unix "1-5" (Mon-Fri) → Quartz "2-6" (Mon-Fri)
        let q = super::cron_to_quartz("0 9 * * 1-5");
        assert_eq!(q, "0 0 9 * * 2-6 *");
    }

    #[test]
    fn cron_to_quartz_every_weekday_dow_wildcard() {
        let q = super::cron_to_quartz("0 9 * * *");
        assert_eq!(q, "0 0 9 * * * *");
    }

    #[test]
    fn cron_to_quartz_sunday_zero_maps_to_quartz_one() {
        // unix "0" (Sun) → Quartz "1" (Sun)
        let q = super::cron_to_quartz("0 9 * * 0");
        assert_eq!(q, "0 0 9 * * 1 *");
    }

    #[test]
    fn cron_to_quartz_six_field_passes_through() {
        let q = super::cron_to_quartz("0 0 9 * * 2-6");
        assert_eq!(q, "0 0 9 * * 2-6 *");
    }

    #[test]
    fn cron_next_fire_at_returns_next_occurrence_for_hourly_schedule() {
        use chrono::{Datelike as _, TimeZone, Timelike as _, Utc};
        // 2026-04-02 08:45:00 UTC → next fire for "0 * * * *" is 09:00:00
        let from = Utc.with_ymd_and_hms(2026, 4, 2, 8, 45, 0).unwrap();
        let next = super::cron_next_fire_at("0 * * * *", from).expect("must produce next");
        assert_eq!(next.hour(), 9);
        assert_eq!(next.minute(), 0);
        assert_eq!(next.second(), 0);
        // Suppress unused import warning for Datelike
        let _ = next.day();
    }

    #[test]
    fn cron_next_fire_at_returns_none_for_invalid_expression() {
        use chrono::Utc;
        let result = super::cron_next_fire_at("not_a_cron_expr", Utc::now());
        assert!(result.is_none());
    }

    #[test]
    fn cron_next_fire_at_weekday_schedule_skips_weekend() {
        use chrono::{Datelike as _, TimeZone, Timelike as _, Utc, Weekday};
        // 2026-04-04 is a Saturday.  Next weekday-9am fire is Mon 2026-04-06.
        let from = Utc.with_ymd_and_hms(2026, 4, 4, 9, 0, 0).unwrap();
        let next = super::cron_next_fire_at("0 9 * * 1-5", from).expect("must produce next");
        assert_eq!(next.weekday(), Weekday::Mon);
        assert_eq!(next.hour(), 9);
    }

    // ── Trigger hardening unit tests (Phase 3 items 10-11) ───────────────────

    #[test]
    fn trigger_replay_nonce_is_deterministic() {
        let n1 = super::trigger_replay_nonce("dep123", "node-a", "activation-42");
        let n2 = super::trigger_replay_nonce("dep123", "node-a", "activation-42");
        assert_eq!(n1, n2, "same inputs must produce the same nonce");
        assert_eq!(n1.len(), 64, "SHA-256 hex output is 64 chars");
    }

    #[test]
    fn trigger_replay_nonce_differs_for_different_activation_ids() {
        let n1 = super::trigger_replay_nonce("dep123", "node-a", "activation-1");
        let n2 = super::trigger_replay_nonce("dep123", "node-a", "activation-2");
        assert_ne!(n1, n2);
    }

    #[test]
    fn trigger_replay_nonce_differs_for_different_deployments() {
        let n1 = super::trigger_replay_nonce("dep-A", "node-a", "activation-1");
        let n2 = super::trigger_replay_nonce("dep-B", "node-a", "activation-1");
        assert_ne!(n1, n2);
    }

    #[test]
    fn trigger_next_retry_at_returns_rfc3339() {
        let t = super::trigger_next_retry_at(0, 30);
        chrono::DateTime::parse_from_rfc3339(&t).expect("must be valid RFC-3339");
    }

    #[test]
    fn trigger_next_retry_at_increases_with_retry_count() {
        let t0 = chrono::DateTime::parse_from_rfc3339(&super::trigger_next_retry_at(0, 30))
            .unwrap()
            .timestamp();
        let t1 = chrono::DateTime::parse_from_rfc3339(&super::trigger_next_retry_at(1, 30))
            .unwrap()
            .timestamp();
        let t2 = chrono::DateTime::parse_from_rfc3339(&super::trigger_next_retry_at(2, 30))
            .unwrap()
            .timestamp();
        assert!(t1 > t0, "retry 1 must be later than retry 0");
        assert!(t2 > t1, "retry 2 must be later than retry 1");
    }

    #[test]
    fn trigger_next_retry_at_is_capped_at_one_hour() {
        // At retry 20 (well past the exponent cap) the delay should be 3600 s.
        let now = chrono::Utc::now().timestamp();
        let t = chrono::DateTime::parse_from_rfc3339(&super::trigger_next_retry_at(20, 30))
            .unwrap()
            .timestamp();
        let delay = t - now;
        assert!(delay <= 3601, "delay must be capped at 3600s; got {delay}s");
        assert!(delay >= 3599, "delay should be ~3600s; got {delay}s");
    }

    #[test]
    fn dedup_hash_is_sha256_hex() {
        // Verify that the dedup_hash generation in the deploy path uses
        // a deterministic, collision-resistant algorithm (SHA-256) rather
        // than the non-deterministic DefaultHasher.
        use sha2::{Digest, Sha256};
        let descriptor = serde_json::json!({"trigger_family": "time", "trigger_kind": "schedule"});
        let mut h = Sha256::new();
        h.update(descriptor.to_string().as_bytes());
        let expected = format!("{:x}", h.finalize());
        assert_eq!(expected.len(), 64);

        // Running twice must yield the same hash.
        let mut h2 = Sha256::new();
        h2.update(descriptor.to_string().as_bytes());
        let expected2 = format!("{:x}", h2.finalize());
        assert_eq!(expected, expected2, "SHA-256 must be deterministic");
    }

    #[test]
    fn dedup_hash_differs_for_different_descriptors() {
        use sha2::{Digest, Sha256};
        let d1 = serde_json::json!({"trigger_kind": "schedule"});
        let d2 = serde_json::json!({"trigger_kind": "email"});
        let hash = |d: &serde_json::Value| -> String {
            let mut h = Sha256::new();
            h.update(d.to_string().as_bytes());
            format!("{:x}", h.finalize())
        };
        assert_ne!(hash(&d1), hash(&d2));
    }

