    #[test]
    fn webhook_ingress_route_family_filter_allows_webhook_kinds() {
        // Verify the family/kind strings that should trigger route insertion.
        let webhook_kinds = ["webhook", "api_callback", "http_push"];
        for kind in &webhook_kinds {
            assert!(
                matches!(*kind, "webhook" | "api_callback" | "http_push"),
                "{kind} should be routed to webhook ingress"
            );
        }
        // Non-webhook kinds must not match.
        let non_webhook = ["email", "file_drop", "cron", "manual", "scheduled"];
        for kind in &non_webhook {
            assert!(
                !matches!(*kind, "webhook" | "api_callback" | "http_push"),
                "{kind} must not be routed to webhook ingress"
            );
        }
    }

